219	func dispatchBranches(dispatch *Dispatch) []string {
220		seen := map[string]struct{}{}
221		branches := make([]string, 0)
222		for _, repo := range dispatch.Repos {
223			for _, section := range repo.Sections {
224				for _, bullet := range section.Bullets {
225					branch := strings.TrimSpace(bullet.Branch)
226					if branch == "" {
227						continue
228					}
229					if _, ok := seen[branch]; ok {
230						continue
231					}
232					seen[branch] = struct{}{}
233					branches = append(branches, branch)
234				}
235			}
236		}
237		return branches
238	}
