240	func formatDispatchTime(value time.Time) string {
241		if value.IsZero() {
242			return ""
243		}
244		return value.UTC().Format(time.RFC3339)
245	}
246	
247	func formatOptionalDispatchTime(value time.Time) *string {
248		if value.IsZero() {
249			return nil
250		}
251		formatted := formatDispatchTime(value)
252		return &formatted
253	}
