213		case strings.TrimSpace(opts.Org) != "":
214			scope = "org:" + strings.TrimSpace(opts.Org)
215		case len(opts.RepoPaths) > 0:
216			scope = "repos:" + strings.Join(opts.RepoPaths, ", ")
217		}
218	
219		branches := "current branch"
220		if opts.AllBranches {
221			branches = "all"
222		} else if opts.Mode == dispatchpkg.ModeLocal {
223			branches = "current branch"
224		} else if len(opts.Branches) > 0 {
225			branches = strings.Join(opts.Branches, ", ")
226		} else if strings.TrimSpace(opts.Org) != "" || len(opts.RepoPaths) > 0 {
227			branches = "default branches"
228		}
229	
230		mode := "cloud"
231		if opts.Mode == dispatchpkg.ModeLocal {
232			mode = "local"
233		}
234	
235		return strings.Join([]string{
236			"Mode: " + mode,
237			"Scope: " + scope,
238			"Branches: " + branches,
239		}, "\n")
240	}
