610	func discoverAuthenticatedDispatchWizardRepos(ctx context.Context) ([]string, error) {
611		cmd := exec.CommandContext(
612			ctx,
613			"gh",
614			"api",
615			"--paginate",
616			"user/repos?per_page=100&affiliation=owner,collaborator,organization_member&sort=full_name",
617			"--jq",
618			".[].full_name",
619		)
620		output, err := cmd.Output()
621		if err != nil {
622			return nil, err
623		}
624	
625		repos := make([]string, 0)
626		seen := make(map[string]struct{})
627		for _, line := range strings.Split(string(output), "\n") {
628			line = strings.TrimSpace(line)
629			if line == "" {
630				continue
631			}
632			if _, ok := seen[line]; ok {
633				continue
634			}
635			seen[line] = struct{}{}
636			repos = append(repos, line)
637		}
638		sort.Strings(repos)
639		return repos, nil
640	}
