642	func discoverRepoSlug(repoRoot string) string {
643		repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{DetectDotGit: true})
644		if err != nil {
645			return ""
646		}
647		remote, err := repo.Remote("origin")
648		if err != nil || len(remote.Config().URLs) == 0 {
649			return ""
650		}
651		owner, repoName, err := searchpkg.ParseGitHubRemote(remote.Config().URLs[0])
652		if err != nil {
653			return ""
654		}
655		return owner + "/" + repoName
656	}
