58	func defaultRunInteractiveDispatch(ctx context.Context, outW io.Writer, opts dispatchpkg.Options) (string, error) {
59		runCtx, cancel := context.WithCancel(ctx)
60		defer cancel()
61	
62		model := newDispatchStatusModel(outW, opts, func(runCtx context.Context) (string, error) {
63			result, err := runDispatch(runCtx, opts)
64			if err != nil {
65				return "", err
66			}
67			return renderDispatchMarkdown(result), nil
68		})
69		model.ctx = runCtx
70		model.cancel = cancel
71	
72		program := newDispatchProgram(model, outW, false)
73		finalModel, err := program.Run()
74		if err != nil {
75			return "", err
76		}
77	
78		finished, ok := finalModel.(dispatchStatusModel)
79		if !ok {
80			return "", errors.New("unexpected dispatch loading state")
81		}
82		clearDispatchInlineView(outW, finished.View())
83		if finished.result.err != nil {
84			return "", finished.result.err
85		}
86		return finished.result.markdown, nil
87	}
