23	var (
24		lookupCurrentToken = auth.LookupCurrentToken
25		nowUTC             = func() time.Time { return time.Now().UTC() }
26	)
27	
28	func runLocal(ctx context.Context, opts Options) (*Dispatch, error) {
29		if strings.TrimSpace(opts.Org) != "" {
30			return nil, errors.New("--org cannot be used with --local")
31		}
32	
33		now := nowUTC()
34		sinceInput := strings.TrimSpace(opts.Since)
35		if sinceInput == "" {
36			sinceInput = "7d"
37		}
38		since, err := ParseSinceAtNow(sinceInput, now)
39		if err != nil {
40			return nil, err
41		}
42		until, err := ParseUntilAtNow(opts.Until, now)
43		if err != nil {
44			return nil, err
45		}
46		normalizedSince, normalizedUntil := NormalizeWindow(since, until)
47		if !normalizedSince.Before(normalizedUntil) {
48			return nil, errors.New("--since must be before --until")
49		}
50	
51		repoRoots, err := resolveRepoRoots(ctx, opts.RepoPaths)
52		if err != nil {
53			return nil, err
54		}
55	
56		allCandidates := make([]candidate, 0)
57		var candidatesMu sync.Mutex
58		group, groupCtx := errgroup.WithContext(ctx)
59		for _, repoRoot := range repoRoots {
60			repoRoot := repoRoot
61			group.Go(func() error {
62				candidates, err := enumerateRepoCandidates(groupCtx, repoRoot, opts, normalizedSince, normalizedUntil)
63				if err != nil {
64					return err
65				}
66				candidatesMu.Lock()
67				allCandidates = append(allCandidates, candidates...)
68				candidatesMu.Unlock()
69				return nil
70			})
71		}
72		if err := group.Wait(); err != nil {
73			return nil, err
74		}
75	
76		fallback := applyFallbackChain(allCandidates)
77		dispatch := &Dispatch{
78			CoveredRepos: coveredRepos(allCandidates),
79			Repos:        groupBulletsByRepo(fallback.Used),
80			Totals:       computeTotals(allCandidates, fallback.Used),
81			Warnings:     fallback.Warnings,
82			Window: Window{
83				NormalizedSince:   normalizedSince,
84				NormalizedUntil:   normalizedUntil,
85				FirstCheckpointAt: firstAt(fallback.Used),
86				LastCheckpointAt:  lastAt(fallback.Used),
87			},
88			RequestedGenerate: opts.Generate,
89		}
90	
91		text, err := generateLocalDispatch(ctx, dispatch, opts.Voice)
92		if err != nil {
93			return nil, err
94		}
95		dispatch.GeneratedText = text
96		dispatch.Generated = strings.TrimSpace(text) != ""
97		if !dispatch.Generated {
98			return nil, errDispatchMissingMarkdown
99		}
100	
101		return dispatch, nil
102	}
103	
104	func NormalizeWindow(since, until time.Time) (time.Time, time.Time) {
105		floored := since.Truncate(time.Minute)
106		ceiled := until.Truncate(time.Minute)
107		if !until.Equal(ceiled) {
108			ceiled = ceiled.Add(time.Minute)
109		}
110		return floored, ceiled
111	}
112	
113	func resolveRepoRoots(ctx context.Context, repoPaths []string) ([]string, error) {
114		if len(repoPaths) == 0 {
115			repoRoot, err := paths.WorktreeRoot(ctx)
116			if err != nil {
117				return nil, fmt.Errorf("not in a git repository: %w", err)
118			}
119			return []string{repoRoot}, nil
120		}
121	
122		roots := make([]string, 0, len(repoPaths))
123		for _, repoPath := range repoPaths {
124			cmd := exec.CommandContext(ctx, "git", "-C", repoPath, "rev-parse", "--show-toplevel")
125			output, err := cmd.Output()
126			if err != nil {
127				return nil, fmt.Errorf("resolve repo root for %q: %w", repoPath, err)
128			}
129			roots = append(roots, strings.TrimSpace(string(output)))
130		}
131		return roots, nil
132	}
133	
134	func enumerateRepoCandidates(ctx context.Context, repoRoot string, opts Options, since, until time.Time) ([]candidate, error) {
135		repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{DetectDotGit: true})
136		if err != nil {
137			return nil, fmt.Errorf("open repository %s: %w", repoRoot, err)
138		}
139	
140		repoFullName, err := resolveRepoFullName(repo)
141		if err != nil {
142			return nil, fmt.Errorf("resolve repo name for %s: %w", repoRoot, err)
143		}
144	
145		branches := opts.Branches
146		if len(branches) == 0 && !opts.AllBranches {
147			currentBranch, err := currentBranchName(repo)
148			if err != nil {
149				return nil, err
150			}
151			branches = []string{currentBranch}
152		}
153		branchSet := make(map[string]struct{}, len(branches))
154		for _, branch := range branches {
155			branchSet[branch] = struct{}{}
156		}
157		reachableCheckpointIDs := map[string]struct{}{}
158		if opts.ImplicitCurrentBranch && !opts.AllBranches {
159			reachableCheckpointIDs, err = reachableCheckpointIDsOnHEAD(ctx, repoRoot)
160			if err != nil {
161				return nil, err
162			}
163		}
164	
165		store := checkpoint.NewGitStore(repo)
166		infos, err := store.ListCommitted(ctx)
167		if err != nil {
168			return nil, fmt.Errorf("list committed checkpoints: %w", err)
169		}
170	
171		candidates := make([]candidate, 0, len(infos))
172		for _, info := range infos {
173			if info.CreatedAt.Before(since) || !info.CreatedAt.Before(until) {
174				continue
175			}
176	
177			summary, err := store.ReadCommitted(ctx, info.CheckpointID)
178			if err != nil || summary == nil {
179				continue
180			}
181			if !opts.AllBranches {
182				if opts.ImplicitCurrentBranch {
183					if _, ok := branchSet[summary.Branch]; ok {
184						// The checkpoint was recorded on the current branch, so include it
185						// even if HEAD no longer has a reachable trailer for that ID.
186					} else if _, ok := reachableCheckpointIDs[info.CheckpointID.String()]; !ok {
187						continue
188					}
189				} else {
190					if _, ok := branchSet[summary.Branch]; !ok {
191						continue
192					}
193				}
194			}
195	
196			localSummary := ""
197			if len(summary.Sessions) > 0 {
198				latestIndex := len(summary.Sessions) - 1
199				if metadata, err := store.ReadSessionMetadata(ctx, info.CheckpointID, latestIndex); err == nil && metadata != nil && metadata.Summary != nil {
200					localSummary = strings.TrimSpace(metadata.Summary.Outcome)
201					if localSummary == "" {
202						localSummary = strings.TrimSpace(metadata.Summary.Intent)
203					}
204				}
205			}
206	
207			commitSubject, _ := findCommitSubjectByCheckpoint(ctx, repoRoot, info.CheckpointID)
208			candidates = append(candidates, candidate{
209				CheckpointID:      info.CheckpointID.String(),
210				RepoFullName:      repoFullName,
211				Branch:            summary.Branch,
212				CreatedAt:         info.CreatedAt,
213				FilesTouched:      append([]string(nil), info.FilesTouched...),
214				CommitSubject:     commitSubject,
215				LocalSummaryTitle: localSummary,
216			})
217		}
218	
219		return candidates, nil
220	}
221	
222	func reachableCheckpointIDsOnHEAD(ctx context.Context, repoRoot string) (map[string]struct{}, error) {
223		cmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "log", "HEAD", "--format=%B%x00")
224		output, err := cmd.Output()
225		if err != nil {
226			return nil, fmt.Errorf("list HEAD checkpoint trailers: %w", err)
227		}
228	
229		reachable := make(map[string]struct{})
230		for _, message := range strings.Split(string(output), "\x00") {
231			for _, checkpointID := range trailers.ParseAllCheckpoints(message) {
232				reachable[checkpointID.String()] = struct{}{}
233			}
234		}
235		return reachable, nil
236	}
237	
238	func resolveRepoFullName(repo *git.Repository) (string, error) {
239		remote, err := repo.Remote("origin")
240		if err != nil {
241			return "", fmt.Errorf("find origin remote: %w", err)
242		}
243		if len(remote.Config().URLs) == 0 {
244			return "", errors.New("origin remote has no URLs configured")
245		}
246	
247		owner, repoName, err := search.ParseGitHubRemote(remote.Config().URLs[0])
248		if err != nil {
249			return "", err
250		}
251		return owner + "/" + repoName, nil
252	}
253	
254	func currentBranchName(repo *git.Repository) (string, error) {
255		head, err := repo.Head()
256		if err != nil {
257			return "", fmt.Errorf("get HEAD: %w", err)
258		}
259		if !head.Name().IsBranch() {
260			return "", errors.New("not on a branch (detached HEAD)")
261		}
262		return head.Name().Short(), nil
263	}
264	
265	func findCommitSubjectByCheckpoint(ctx context.Context, repoRoot string, checkpointID checkpointid.CheckpointID) (string, error) {
266		cmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "log", "--all", "--format=%s%x00", "--grep", "Entire-Checkpoint: "+checkpointID.String())
267		output, err := cmd.Output()
268		if err != nil {
269			return "", err
270		}
271		parts := strings.SplitN(string(output), "\x00", 2)
272		if len(parts) == 0 {
273			return "", nil
274		}
275		return strings.TrimSpace(parts[0]), nil
276	}
277	
278	func groupCandidatesByRepo(candidates []candidate) map[string][]string {
279		grouped := make(map[string][]string)
280		for _, candidate := range candidates {
281			grouped[candidate.RepoFullName] = append(grouped[candidate.RepoFullName], candidate.CheckpointID)
282		}
283		return grouped
284	}
285	
286	func coveredRepos(candidates []candidate) []string {
287		if len(candidates) == 0 {
288			return nil
289		}
290	
291		repoSet := make(map[string]struct{}, len(candidates))
292		for _, candidate := range candidates {
293			if candidate.RepoFullName == "" {
294				continue
295			}
296			repoSet[candidate.RepoFullName] = struct{}{}
297		}
298	
299		repos := make([]string, 0, len(repoSet))
300		for repoFullName := range repoSet {
301			repos = append(repos, repoFullName)
302		}
303		sort.Strings(repos)
304		return repos
305	}
306	
307	func groupBulletsByRepo(used []repoBullet) []RepoGroup {
308		repoMap := make(map[string]map[string][]Bullet)
309		for _, item := range used {
310			if _, ok := repoMap[item.RepoFullName]; !ok {
311				repoMap[item.RepoFullName] = make(map[string][]Bullet)
312			}
313			label := "Updates"
314			if len(item.Bullet.Labels) > 0 && strings.TrimSpace(item.Bullet.Labels[0]) != "" {
315				label = item.Bullet.Labels[0]
316			}
317			repoMap[item.RepoFullName][label] = append(repoMap[item.RepoFullName][label], item.Bullet)
318		}
319	
320		repoNames := make([]string, 0, len(repoMap))
321		for repoName := range repoMap {
322			repoNames = append(repoNames, repoName)
323		}
324		sort.Strings(repoNames)
325	
326		out := make([]RepoGroup, 0, len(repoNames))
327		for _, repoName := range repoNames {
328			sectionMap := repoMap[repoName]
329			labels := make([]string, 0, len(sectionMap))
330			for label := range sectionMap {
331				labels = append(labels, label)
332			}
333			sort.Strings(labels)
334	
335			sections := make([]Section, 0, len(labels))
336			for _, label := range labels {
337				sections = append(sections, Section{
338					Label:   label,
339					Bullets: sectionMap[label],
340				})
341			}
342			out = append(out, RepoGroup{FullName: repoName, Sections: sections})
343		}
344	
345		return out
346	}
347	
348	func computeTotals(candidates []candidate, used []repoBullet) Totals {
349		branches := make(map[string]struct{})
350		filesTouched := make(map[string]struct{})
351		for _, candidate := range candidates {
352			if candidate.Branch != "" {
353				branches[candidate.Branch] = struct{}{}
354			}
355			for _, file := range candidate.FilesTouched {
356				filesTouched[file] = struct{}{}
357			}
358		}
359	
360		return Totals{
361			Checkpoints:         len(candidates),
362			UsedCheckpointCount: len(used),
363			Branches:            len(branches),
364			FilesTouched:        len(filesTouched),
365		}
366	}
367	
368	func firstAt(used []repoBullet) time.Time {
369		var first time.Time
370		for _, item := range used {
371			if item.Bullet.CreatedAt.IsZero() {
372				continue
373			}
374			if first.IsZero() || item.Bullet.CreatedAt.Before(first) {
375				first = item.Bullet.CreatedAt
376			}
377		}
378		return first
379	}
380	
381	func lastAt(used []repoBullet) time.Time {
382		var last time.Time
383		for _, item := range used {
384			if item.Bullet.CreatedAt.After(last) {
385				last = item.Bullet.CreatedAt
386			}
387		}
388		return last
389	}
