78	func (c *Client) Put(ctx context.Context, path string, body any) (*http.Response, error) {
79		var reader io.Reader
80		if body != nil {
81			data, err := json.Marshal(body)
82			if err != nil {
83				return nil, fmt.Errorf("marshal request body: %w", err)
84			}
85			reader = bytes.NewReader(data)
86		}
87		return c.do(ctx, http.MethodPut, path, reader)
88	}
