91	func (c *Client) Patch(ctx context.Context, path string, body any) (*http.Response, error) {
92		var reader io.Reader
93		if body != nil {
94			data, err := json.Marshal(body)
95			if err != nil {
96				return nil, fmt.Errorf("marshal request body: %w", err)
97			}
98			reader = bytes.NewReader(data)
99		}
100		return c.do(ctx, http.MethodPatch, path, reader)
101	}
